// A single type is one definition. These two collide — merge them into one.
type Lab = { code: string };
type Lab = { seats: number };
export function describe(lab: Lab): string {
  return lab.code + ' (' + lab.seats + ' seats)';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe } from '../src/app.ts';
test('describe a lab', () => { assert.equal(describe({ code: 'BE-201', seats: 30 }), 'BE-201 (30 seats)'); });

