// These two interfaces merge — but `code` is declared with two different types.
interface Lab { code: string; }
interface Lab { code: number; }
export function labId(lab: Lab): string {
  return String(lab.code);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { labId } from '../src/app.ts';
test('lab id is the code as a string', () => { assert.equal(labId({ code: 'BE-201', seats: 30 }), 'BE-201'); });

